def test_TypeAliasForwardRef():
    alias = TypeAliasForwardRef('example')
    sig_str = stringify_annotation(alias, 'fully-qualified-except-typing')
    assert sig_str == "TypeAliasForwardRef('example')"

    alias = Optional[alias]  # NoQA: UP045
    sig_str = stringify_annotation(alias, 'fully-qualified-except-typing')
