    icon = self.config.html_permalinks_icon
    if node['ids'] and self.config.html_permalinks and self.builder.add_permalinks:
        self.body.append(
            f'<a class="headerlink" href="#{node["ids"][0]}" title="{title}">{icon}</a>',
