    if self.list_counter[-1] == -1:
        # bullet list
        self.new_state(2)
    elif self.list_counter[-1] == -2:
        # definition list
        pass
    else:
        # enumerated list
        self.list_counter[-1] += 1
        self.new_state(len(str(self.list_counter[-1])) + 2)

